using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9: default discriminator property renamed from "Discriminator" to "$type".
            // Existing documents and direct SQL queries use "Discriminator", so preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9: id values no longer include the discriminator (e.g. "123" instead of "Product|123").
            // Existing 500K documents use the old compound format; keep it so FindAsync/point-reads still work.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // HasIndex removed — EF Core 9 Cosmos provider throws at startup.
        // Cosmos DB indexing is managed via the container's indexing policy (Azure Portal/Bicep/Terraform).
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

